import{_ as e,o as l,c as d,a5 as n}from"./chunks/framework.URF5zJ_R.js";const f=JSON.parse(`{"title":"42 Composants Fondamentaux d'Architecture (Building Blocks)","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"fr/05_Building_Blocks.md","filePath":"fr/05_Building_Blocks.md","lastUpdated":1789004603000}`),s={name:"fr/05_Building_Blocks.md"};function o(a,t,i,c,r,g){return l(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="_42-composants-fondamentaux-d-architecture-building-blocks" tabindex="-1">42 Composants Fondamentaux d&#39;Architecture (Building Blocks) <a class="header-anchor" href="#_42-composants-fondamentaux-d-architecture-building-blocks" aria-label="Permalink to &quot;42 Composants Fondamentaux d&#39;Architecture (Building Blocks)&quot;">​</a></h1><p><strong>Total des Éléments</strong>: 42</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Composant</th><th style="text-align:left;">Catégorie</th><th style="text-align:left;">Role</th><th style="text-align:left;">When to Use</th><th style="text-align:left;">⚠️ Anti-patron (Quand NE PAS utiliser)</th><th style="text-align:left;">Outils</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Load balancer</strong></td><td style="text-align:left;"><code>**Traffic**</code></td><td style="text-align:left;">Distributes requests across multiple servers</td><td style="text-align:left;">Any system with more than one server</td><td style="text-align:left;">⚠️ A single-instance internal tool where it adds needless complexity</td><td style="text-align:left;"><code>Nginx</code> <code>HAProxy</code> <code>AWS ALB</code> <code>Envoy</code></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Reverse proxy</strong></td><td style="text-align:left;"><code>**Traffic**</code></td><td style="text-align:left;">Sits in front of servers handling TLS, routing and buffering</td><td style="text-align:left;">Terminating TLS, serving static files, hiding internal topology</td><td style="text-align:left;">⚠️ When your framework already handles it well at low scale</td><td style="text-align:left;"><code>Nginx</code> <code>Caddy</code> <code>Envoy</code> <code>Traefik</code></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>API gateway</strong></td><td style="text-align:left;"><code>**Traffic**</code></td><td style="text-align:left;">Single entry point handling auth, routing, rate limiting and quotas</td><td style="text-align:left;">Microservices with multiple clients</td><td style="text-align:left;">⚠️ A single service where it becomes an unnecessary hop</td><td style="text-align:left;"><code>Kong</code> <code>AWS API Gateway</code> <code>Apigee</code> <code>Envoy</code></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>CDN</strong></td><td style="text-align:left;"><code>**Traffic**</code></td><td style="text-align:left;">Caches content at edge locations near users</td><td style="text-align:left;">Static assets, images, video, and any global audience</td><td style="text-align:left;">⚠️ Highly personalised, uncacheable content</td><td style="text-align:left;"><code>Cloudflare</code> <code>Akamai</code> <code>CloudFront</code> <code>Fastly</code></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>DNS load balancing</strong></td><td style="text-align:left;"><code>**Traffic**</code></td><td style="text-align:left;">Routes users to the nearest or healthiest region</td><td style="text-align:left;">Multi-region deployments</td><td style="text-align:left;">⚠️ Fine-grained routing; DNS caching makes failover slow</td><td style="text-align:left;"><code>Route 53</code> <code>Cloudflare DNS</code></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Application cache</strong></td><td style="text-align:left;"><code>**Caching**</code></td><td style="text-align:left;">In-memory storage of frequently accessed data</td><td style="text-align:left;">Read-heavy workloads with tolerable staleness</td><td style="text-align:left;">⚠️ Data that must always be perfectly current</td><td style="text-align:left;"><code>Redis</code> <code>Memcached</code> <code>Valkey</code></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Local/in-process cache</strong></td><td style="text-align:left;"><code>**Caching**</code></td><td style="text-align:left;">Cache inside the application process</td><td style="text-align:left;">Very hot, small, rarely changing data</td><td style="text-align:left;">⚠️ Multi-instance deployments needing consistency</td><td style="text-align:left;"><code>Caffeine</code> <code>Guava</code> <code>in-memory maps</code></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Database read replica</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Read-only copies of the primary database</td><td style="text-align:left;">Read-heavy workloads that tolerate replication lag</td><td style="text-align:left;">⚠️ Read-your-writes requirements without extra handling</td><td style="text-align:left;"><code>Postgres streaming replication</code> <code>MySQL replicas</code></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Relational database</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">ACID transactions with a fixed schema and joins</td><td style="text-align:left;">Anything with relationships and correctness requirements</td><td style="text-align:left;">⚠️ Extreme write scale or genuinely schemaless data</td><td style="text-align:left;"><code>PostgreSQL</code> <code>MySQL</code> <code>Aurora</code></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>Wide-column store</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Distributed store optimised for very high write volume</td><td style="text-align:left;">Time series, event data, messaging at massive scale</td><td style="text-align:left;">⚠️ Complex queries and joins</td><td style="text-align:left;"><code>Cassandra</code> <code>ScyllaDB</code> <code>HBase</code> <code>Bigtable</code></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>Document database</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Flexible schema, document-oriented storage</td><td style="text-align:left;">Evolving schemas and nested data</td><td style="text-align:left;">⚠️ Heavy relational joins and multi-document transactions</td><td style="text-align:left;"><code>MongoDB</code> <code>DynamoDB</code> <code>Firestore</code></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>Key-value store</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Simple, extremely fast lookups by key</td><td style="text-align:left;">Sessions, caching, feature flags, simple lookups</td><td style="text-align:left;">⚠️ Any query that is not by primary key</td><td style="text-align:left;"><code>Redis</code> <code>DynamoDB</code> <code>etcd</code></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>Graph database</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Stores and traverses relationships as first-class data</td><td style="text-align:left;">Social graphs, fraud rings, recommendations</td><td style="text-align:left;">⚠️ Simple tabular data with no traversal</td><td style="text-align:left;"><code>Neo4j</code> <code>Neptune</code> <code>JanusGraph</code></td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>Time-series database</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Optimised for timestamped metrics with downsampling</td><td style="text-align:left;">Monitoring, IoT, financial ticks</td><td style="text-align:left;">⚠️ General-purpose transactional data</td><td style="text-align:left;"><code>InfluxDB</code> <code>TimescaleDB</code> <code>Prometheus</code></td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>Search index</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Full-text search, faceting and relevance ranking</td><td style="text-align:left;">Any product with a search box</td><td style="text-align:left;">⚠️ Exact lookups your primary database handles fine</td><td style="text-align:left;"><code>Elasticsearch</code> <code>OpenSearch</code> <code>Solr</code> <code>Typesense</code></td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>OLAP / data warehouse</strong></td><td style="text-align:left;"><code>**Database**</code></td><td style="text-align:left;">Columnar storage for analytical aggregation</td><td style="text-align:left;">Dashboards, reporting, business analytics</td><td style="text-align:left;">⚠️ Transactional, row-level operations</td><td style="text-align:left;"><code>Snowflake</code> <code>BigQuery</code> <code>ClickHouse</code> <code>Redshift</code></td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>Object storage</strong></td><td style="text-align:left;"><code>**Storage**</code></td><td style="text-align:left;">Cheap, durable storage for large unstructured blobs</td><td style="text-align:left;">Images, video, backups, data lakes</td><td style="text-align:left;">⚠️ Low-latency random access or transactional data</td><td style="text-align:left;"><code>S3</code> <code>GCS</code> <code>Azure Blob</code> <code>MinIO</code></td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>Block storage</strong></td><td style="text-align:left;"><code>**Storage**</code></td><td style="text-align:left;">Persistent disk attached to a compute instance</td><td style="text-align:left;">Databases and anything needing a filesystem</td><td style="text-align:left;">⚠️ Sharing across many instances simultaneously</td><td style="text-align:left;"><code>EBS</code> <code>Persistent Disk</code></td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>Message queue</strong></td><td style="text-align:left;"><code>**Messaging**</code></td><td style="text-align:left;">Buffers work between producer and consumer</td><td style="text-align:left;">Decoupling, absorbing spikes, background work</td><td style="text-align:left;">⚠️ Genuinely synchronous request-response needs</td><td style="text-align:left;"><code>RabbitMQ</code> <code>SQS</code> <code>Redis Streams</code></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>Event log / stream</strong></td><td style="text-align:left;"><code>**Messaging**</code></td><td style="text-align:left;">Durable, replayable, ordered append-only log</td><td style="text-align:left;">Event sourcing, multiple consumers, replay capability</td><td style="text-align:left;">⚠️ Simple task queues where it is overkill</td><td style="text-align:left;"><code>Kafka</code> <code>Pulsar</code> <code>Kinesis</code> <code>Redpanda</code></td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>Pub/sub</strong></td><td style="text-align:left;"><code>**Messaging**</code></td><td style="text-align:left;">One publisher, many independent subscribers</td><td style="text-align:left;">Fan-out notifications and event broadcasting</td><td style="text-align:left;">⚠️ Guaranteed single-consumer processing</td><td style="text-align:left;"><code>Kafka</code> <code>Google Pub/Sub</code> <code>SNS</code> <code>NATS</code></td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>Task scheduler</strong></td><td style="text-align:left;"><code>**Compute**</code></td><td style="text-align:left;">Runs jobs on a schedule or after a delay</td><td style="text-align:left;">Reports, cleanups, reminders, retries</td><td style="text-align:left;">⚠️ Immediate synchronous work</td><td style="text-align:left;"><code>Airflow</code> <code>Temporal</code> <code>Quartz</code> <code>cron</code></td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>Worker pool</strong></td><td style="text-align:left;"><code>**Compute**</code></td><td style="text-align:left;">Processes queued jobs asynchronously</td><td style="text-align:left;">Any work too slow for the request cycle</td><td style="text-align:left;">⚠️ Sub-millisecond operations</td><td style="text-align:left;"><code>Celery</code> <code>Sidekiq</code> <code>BullMQ</code> <code>Hangfire</code></td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>Serverless functions</strong></td><td style="text-align:left;"><code>**Compute**</code></td><td style="text-align:left;">Event-triggered compute with no server management</td><td style="text-align:left;">Spiky, low-volume, event-driven workloads</td><td style="text-align:left;">⚠️ Long-running or latency-critical work (cold starts)</td><td style="text-align:left;"><code>Lambda</code> <code>Cloud Functions</code> <code>Azure Functions</code></td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>Container orchestrator</strong></td><td style="text-align:left;"><code>**Compute**</code></td><td style="text-align:left;">Schedules, scales and heals containerised services</td><td style="text-align:left;">Multi-service systems at meaningful scale</td><td style="text-align:left;">⚠️ A single small service; the complexity is not free</td><td style="text-align:left;"><code>Kubernetes</code> <code>ECS</code> <code>Nomad</code></td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>Stream processor</strong></td><td style="text-align:left;"><code>**Processing**</code></td><td style="text-align:left;">Continuous computation over event streams</td><td style="text-align:left;">Real-time aggregation, windowing, enrichment</td><td style="text-align:left;">⚠️ Batch work with no latency requirement</td><td style="text-align:left;"><code>Flink</code> <code>Kafka Streams</code> <code>Spark Streaming</code></td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>Batch processor</strong></td><td style="text-align:left;"><code>**Processing**</code></td><td style="text-align:left;">Large-scale scheduled data processing</td><td style="text-align:left;">Nightly reports, ETL, model training data</td><td style="text-align:left;">⚠️ Anything needing sub-minute freshness</td><td style="text-align:left;"><code>Spark</code> <code>Hadoop</code> <code>dbt</code> <code>Airflow</code></td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>Rate limiter</strong></td><td style="text-align:left;"><code>**Reliability**</code></td><td style="text-align:left;">Caps request rate per user, key or tenant</td><td style="text-align:left;">Any public API or abuse-prone endpoint</td><td style="text-align:left;">⚠️ Trusted internal traffic with known volume</td><td style="text-align:left;"><code>Redis counters</code> <code>Envoy</code> <code>API gateway policies</code></td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>Circuit breaker</strong></td><td style="text-align:left;"><code>**Reliability**</code></td><td style="text-align:left;">Stops calling a failing dependency to allow recovery</td><td style="text-align:left;">Any synchronous call to another service</td><td style="text-align:left;">⚠️ Local in-process calls</td><td style="text-align:left;"><code>Resilience4j</code> <code>Polly</code> <code>Hystrix</code> <code>Envoy</code></td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>Service discovery</strong></td><td style="text-align:left;"><code>**Reliability**</code></td><td style="text-align:left;">Lets services find each other dynamically</td><td style="text-align:left;">Dynamic environments where instances come and go</td><td style="text-align:left;">⚠️ Fixed, small, static deployments</td><td style="text-align:left;"><code>Consul</code> <code>Eureka</code> <code>Kubernetes DNS</code></td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>Service mesh</strong></td><td style="text-align:left;"><code>**Reliability**</code></td><td style="text-align:left;">Handles service-to-service traffic, security and telemetry</td><td style="text-align:left;">Large microservice estates</td><td style="text-align:left;">⚠️ Fewer than about ten services; the overhead dominates</td><td style="text-align:left;"><code>Istio</code> <code>Linkerd</code> <code>Consul Connect</code></td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>Distributed lock</strong></td><td style="text-align:left;"><code>**Coordination**</code></td><td style="text-align:left;">Ensures only one process performs an action</td><td style="text-align:left;">Leader election, preventing duplicate job execution</td><td style="text-align:left;">⚠️ When idempotency would solve it more simply</td><td style="text-align:left;"><code>Redis Redlock</code> <code>ZooKeeper</code> <code>etcd</code></td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>Consensus / coordination service</strong></td><td style="text-align:left;"><code>**Coordination**</code></td><td style="text-align:left;">Agreement on shared state across nodes</td><td style="text-align:left;">Leader election, configuration, cluster membership</td><td style="text-align:left;">⚠️ Simple systems where a database suffices</td><td style="text-align:left;"><code>ZooKeeper</code> <code>etcd</code> <code>Consul</code></td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>Configuration service</strong></td><td style="text-align:left;"><code>**Coordination**</code></td><td style="text-align:left;">Centralised, dynamic application configuration</td><td style="text-align:left;">Many services needing consistent, changeable config</td><td style="text-align:left;">⚠️ A single service where environment variables work</td><td style="text-align:left;"><code>Consul</code> <code>Spring Cloud Config</code> <code>AppConfig</code></td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>Feature flag service</strong></td><td style="text-align:left;"><code>**Coordination**</code></td><td style="text-align:left;">Toggles behaviour without a deployment</td><td style="text-align:left;">Gradual rollouts, kill switches, experiments</td><td style="text-align:left;">⚠️ Very small teams shipping infrequently</td><td style="text-align:left;"><code>LaunchDarkly</code> <code>Unleash</code> <code>Flagsmith</code></td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>Metrics and monitoring</strong></td><td style="text-align:left;"><code>**Observability**</code></td><td style="text-align:left;">Collects and stores numeric time-series signals</td><td style="text-align:left;">Every production system without exception</td><td style="text-align:left;">⚠️ Never; this is not optional</td><td style="text-align:left;"><code>Prometheus</code> <code>Grafana</code> <code>Datadog</code> <code>CloudWatch</code></td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>Distributed tracing</strong></td><td style="text-align:left;"><code>**Observability**</code></td><td style="text-align:left;">Follows a single request across many services</td><td style="text-align:left;">Any system with more than about three services</td><td style="text-align:left;">⚠️ A monolith where logs suffice</td><td style="text-align:left;"><code>Jaeger</code> <code>Tempo</code> <code>OpenTelemetry</code> <code>Zipkin</code></td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>Centralised logging</strong></td><td style="text-align:left;"><code>**Observability**</code></td><td style="text-align:left;">Aggregates and indexes logs from all services</td><td style="text-align:left;">Any multi-instance deployment</td><td style="text-align:left;">⚠️ A single server you can SSH into</td><td style="text-align:left;"><code>ELK</code> <code>Loki</code> <code>Splunk</code> <code>Datadog</code></td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>Error tracking</strong></td><td style="text-align:left;"><code>**Observability**</code></td><td style="text-align:left;">Captures, groups and alerts on exceptions</td><td style="text-align:left;">Every user-facing application</td><td style="text-align:left;">⚠️ Never; the free tiers make this trivial</td><td style="text-align:left;"><code>Sentry</code> <code>Rollbar</code> <code>Bugsnag</code></td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>Identity provider</strong></td><td style="text-align:left;"><code>**Security**</code></td><td style="text-align:left;">Centralised authentication and token issuance</td><td style="text-align:left;">Any system with users, especially multi-service</td><td style="text-align:left;">⚠️ A single app with simple session auth</td><td style="text-align:left;"><code>Auth0</code> <code>Keycloak</code> <code>Entra ID</code> <code>Cognito</code></td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>Secrets manager</strong></td><td style="text-align:left;"><code>**Security**</code></td><td style="text-align:left;">Stores and rotates credentials securely</td><td style="text-align:left;">Every production system</td><td style="text-align:left;">⚠️ Never; environment variables in git is the failure mode</td><td style="text-align:left;"><code>Vault</code> <code>AWS Secrets Manager</code> <code>Doppler</code></td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>WAF / DDoS protection</strong></td><td style="text-align:left;"><code>**Security**</code></td><td style="text-align:left;">Filters malicious traffic at the edge</td><td style="text-align:left;">Any public-facing service</td><td style="text-align:left;">⚠️ Internal-only services behind a VPN</td><td style="text-align:left;"><code>Cloudflare</code> <code>AWS WAF</code> <code>Akamai</code></td></tr></tbody></table>',3)])])}const x=e(s,[["render",o]]);export{f as __pageData,x as default};
